    "site.gov.nt.s5b": "Cada sección a continuación es obligatoria antes de publicar el aviso: los datos elemento por elemento, los fines, la revocación, los derechos, los destinatarios y el nombre y dirección del hospital (DPDP Rules 2025 r.3; SPDI Rules 2011 r.5(3)), así como el contacto del Oficial de Protección de Datos o Encargado de Reclamaciones. Redáctelo en inglés o en un idioma del Octavo Anexo. Publicar nuevamente genera una nueva versión; los pacientes confirman la recepción de una versión. Desde el inicio de la DPDP, los pacientes que recibieron un aviso previo requieren uno nuevo (s.5(2)).",
